contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: takes all parameters forwarded to setL1BlockValues
    function run(
        address caller,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(address(c) != address(0));
        // read depositorAccount from contract's public getter
        address depositor = c.depositorAccount(); if (__ESBMC_reverted()) return;

        bool callReverted;

        // perform the call as this contract (msg.sender == address(this))
        // If desired caller equals depositor, we expect the call to succeed when relayed from that account.
        // But since the checker always calls c from this test contract, we simulate two cases:
        // - If requested caller != depositor, calling setL1BlockValues from this contract should revert
        //   unless this contract's address equals depositor.
        // - If requested caller == depositor, we require that the depositor getter equals this contract's address
        //   to allow a non-reverting call; otherwise such a call from this contract would revert.

        // Try the call and capture whether it reverts
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            callReverted = true;
        } else {
            callReverted = false;
        }

        // The general rule: callReverted is true iff depositor != address(this).
        // This expresses that only the depositorAccount (as observed via the public getter) may call successfully.
        assert(callReverted == (depositor != address(this)));
    }

    receive() external payable {}
}

